'use strict';
/**
 * auditLog.js — Append-only audit event model.
 *
 * SRS AUD-01: Every status change, price proposal, payment, and release
 *             is written to the audit log with actor and timestamp.
 * SRS AUD-02: No application user can edit or delete log entries.
 *             (Enforced by DB trigger — this layer adds defence in depth.)
 * SRS AUD-03: Timestamps are generated by the server (DB NOW()).
 *
 * USAGE — import logEvent and call it after every significant action:
 *
 *   await logEvent({
 *     jobId:       job.id,
 *     actorUserId: req.user?.id,         // null for customer/system
 *     actorLabel:  req.user?.name || 'customer',
 *     eventType:   AUDIT_EVENT.STATUS_CHANGED,
 *     oldValue:    { status: 'In Queue' },
 *     newValue:    { status: 'Awaiting Confirmation' },
 *     notes:       'Claimed by repairer',
 *   });
 */

const db     = require('../config/db');
const logger = require('../utils/logger');

// ── logEvent ──────────────────────────────────────────────────
/**
 * Insert a new audit log entry. This is the ONLY write function for job_events.
 * It never updates or deletes — the DB trigger enforces immutability there too.
 *
 * Fails silently (logs error but does not throw) so an audit failure never
 * crashes a user-facing transaction. Prefer wrapping in the same DB transaction
 * as the action being logged for atomicity.
 *
 * @param {object}  opts
 * @param {string}  opts.jobId        - UUID of the job
 * @param {string}  [opts.actorUserId]- UUID of the staff user (null = customer/system)
 * @param {string}  opts.actorLabel   - Human label: 'customer'|'system'|staff name
 * @param {string}  opts.eventType    - AUDIT_EVENT constant e.g. 'status_changed'
 * @param {object}  [opts.oldValue]   - Previous state (stored as JSONB)
 * @param {object}  [opts.newValue]   - New state (stored as JSONB)
 * @param {string}  [opts.notes]      - Free-text note
 * @param {object}  [opts.client]     - Optional pg client (for transactions)
 * @returns {Promise<object|null>}    - The created row, or null on failure
 */
const logEvent = async ({
  jobId,
  actorUserId = null,
  actorLabel,
  eventType,
  oldValue = null,
  newValue = null,
  notes = null,
  client = null,        // pass a transaction client for atomicity
}) => {
  const execute = client
    ? (text, params) => client.query(text, params)
    : db.query;

  try {
    const result = await execute(
      `INSERT INTO job_events
         (job_id, actor_user_id, actor_label, event_type, old_value, new_value, notes)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       RETURNING id, created_at`,
      [
        jobId,
        actorUserId,
        actorLabel,
        eventType,
        oldValue  ? JSON.stringify(oldValue)  : null,
        newValue  ? JSON.stringify(newValue)  : null,
        notes,
      ]
    );
    return result.rows[0];
  } catch (err) {
    // Audit failures must never crash the main flow — log and continue
    logger.error('Audit log write failed', {
      jobId,
      eventType,
      error: err.message,
    });
    return null;
  }
};

// ── getJobTimeline ────────────────────────────────────────────
/**
 * Return the full immutable audit timeline for a job, ordered by time.
 * Used by: owner audit page, job detail slide-over, customer status page.
 *
 * @param {string} jobId
 * @returns {Promise<Array>}
 */
const getJobTimeline = async (jobId) => {
  const result = await db.query(
    `SELECT
       je.id,
       je.actor_label,
       je.event_type,
       je.old_value,
       je.new_value,
       je.notes,
       je.created_at,
       u.name AS actor_name
     FROM job_events je
     LEFT JOIN users u ON je.actor_user_id = u.id
     WHERE je.job_id = $1
     ORDER BY je.created_at ASC`,
    [jobId]
  );
  return result.rows;
};

// ── getAuditFeed ──────────────────────────────────────────────
/**
 * Paginated audit feed for the owner audit page.
 * Supports filtering by event_type, actor, date range, and job number prefix.
 *
 * @param {object} filters
 * @param {string}  [filters.jobNumber]   - partial job number search
 * @param {string}  [filters.eventType]   - exact event type match
 * @param {string}  [filters.actorLabel]  - partial actor label match
 * @param {string}  [filters.dateFrom]    - ISO date string
 * @param {string}  [filters.dateTo]      - ISO date string
 * @param {number}  [filters.page=1]
 * @param {number}  [filters.limit=50]
 * @returns {Promise<{ rows: Array, total: number }>}
 */
const getAuditFeed = async ({
  jobNumber,
  eventType,
  actorLabel,
  dateFrom,
  dateTo,
  page  = 1,
  limit = 50,
} = {}) => {
  const conditions = [];
  const params     = [];
  let   p          = 1;

  if (jobNumber) {
    conditions.push(`j.job_number ILIKE $${p++}`);
    params.push(`%${jobNumber}%`);
  }
  if (eventType) {
    conditions.push(`je.event_type = $${p++}`);
    params.push(eventType);
  }
  if (actorLabel) {
    conditions.push(`je.actor_label ILIKE $${p++}`);
    params.push(`%${actorLabel}%`);
  }
  if (dateFrom) {
    conditions.push(`je.created_at >= $${p++}`);
    params.push(dateFrom);
  }
  if (dateTo) {
    conditions.push(`je.created_at <= $${p++}`);
    params.push(dateTo);
  }

  const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  const offset = (page - 1) * limit;

  const [dataResult, countResult] = await Promise.all([
    db.query(
      `SELECT
         je.id,
         j.job_number,
         je.actor_label,
         je.event_type,
         je.old_value,
         je.new_value,
         je.notes,
         je.created_at
       FROM job_events je
       JOIN jobs j ON je.job_id = j.id
       ${where}
       ORDER BY je.created_at DESC
       LIMIT $${p} OFFSET $${p + 1}`,
      [...params, limit, offset]
    ),
    db.query(
      `SELECT COUNT(*) FROM job_events je
       JOIN jobs j ON je.job_id = j.id
       ${where}`,
      params
    ),
  ]);

  return {
    rows:  dataResult.rows,
    total: parseInt(countResult.rows[0].count, 10),
    page,
    limit,
  };
};

module.exports = {
  logEvent,
  getJobTimeline,
  getAuditFeed,
};
